 static BindingFlags s=BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public,i=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static Type web,checker;static int n;const string own="https://github.com/SomJsA/DS2-Severed-Installer/releases";
